package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Integer;
    attribute elapsedAccMs : Integer := 0;
    attribute pendingTrigger : Boolean := false;
    perform action tick {
      first start;
      then assign elapsedAccMs := elapsedAccMs + io_0;
      then if elapsedAccMs >= 2000 {
        first start;
        then assign elapsedAccMs := elapsedAccMs - 2000;
        then assign pendingTrigger := true;
      } else {
        first start;
        then assign pendingTrigger := false;
      }
    }
    out attribute io_1 : Boolean = pendingTrigger;
    out attribute serial_0_trigger : Boolean = pendingTrigger;
    out attribute serial_0_value_0 : Boolean = pendingTrigger;
  }
  part system : Controller;
}
